import sys
from decimal import Decimal


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) != 3:
            continue
        a, op, b = parts[0], parts[1], parts[2]
        try:
            a = Decimal(a)
            b = Decimal(b)
        except:
            print("ERROR")
            continue
        if op == "+":
            result = a + b
        elif op == "-":
            result = a - b
        elif op == "*":
            result = a * b
        elif op == "/":
            if b == 0:
                print("ERROR")
            else:
                result = round(a / b, 10)
        else:
            print("ERROR")
            continue
        if result == 0:
            print("0")
        elif result % 1 == 0:
            print(int(result))
        else:
            s = str(result)
            if "." in s:
                integer_part, fractional_part = s.split(".")
            else:
                integer_part = s
                fractional_part = ""
            if integer_part == "0" and fractional_part == "":
                print(integer_part)
            elif integer_part == "":
                print(fractional_part)
            else:
                print(f"{integer_part}.{fractional_part}")


if __name__ == "__main__":
    main()
